    private static void ClearHappinessFromLegacyStorageFixture(SaveDocument saved)
    {
        // A legacy storage check must fail on storage data, not on unrelated mood fields that did not exist yet.
        for(int i=0;i<saved.actors.Length;i++){saved.actors[i].happiness=0;saved.actors[i].nextHappinessTick=0;}
    }
    private static void SetStorageFixtureTick(SaveDocument saved,long tick)
    {
        // These memory-age fixtures author a new time origin; reschedule mood sampling instead of saving a stale pulse.
        saved.tick=tick;for(int i=0;i<saved.actors.Length;i++)saved.actors[i].nextHappinessTick=0;
    }
